<!doctype html><html lang="fr"><head><meta charset="utf-8"><title><?=e($sale['sale_no'])?></title><link rel="icon" href="<?=e(asset('icons/favicon.svg'))?>"><link rel="stylesheet" href="<?=e(asset('vendor/bootstrap/bootstrap.min.css'))?>"><link rel="stylesheet" href="<?=e(asset('css/app.css'))?>"></head><body><div class="receipt"><div class="text-center"><img src="<?=e(company_logo_url())?>"><div><?=e($settings['company_address']??'')?></div><div><?=e($settings['company_phone']??'')?></div></div><hr><div>Ticket: <strong><?=e($sale['sale_no'])?></strong></div><div>Date: <?=e($sale['created_at'])?></div><div>Caissier: <?=e($sale['cashier'])?></div><?php if($sale['customer']):?><div>Client: <?=e($sale['customer'])?></div><?php endif;?><hr><?php foreach($sale['items'] as $i):?><div class="d-flex justify-content-between"><span><?=e($i['name'])?> x<?=e($i['quantity'])?></span><span><?=money($i['subtotal'])?></span></div><?php endforeach;?><hr><div class="d-flex justify-content-between"><strong>TOTAL</strong><strong><?=money($sale['total'])?></strong></div><?php foreach($sale['payments'] as $p):?><div class="d-flex justify-content-between"><span><?=e($p['method'].' '.$p['currency'])?></span><span><?=money($p['amount'])?></span></div><?php endforeach;?><hr><p class="text-center">Merci pour votre confiance.<br><strong>KIN-MART — Super Marché</strong></p><div class="text-center no-print"><button onclick="window.print()">Imprimer / Enregistrer PDF</button> <a href="<?=e(base_url('pos'))?>">Retour POS</a></div></div></body></html>